        if let model = loaded[id] { return model }
        if let task = loading[id] { return try await task.value }
        let task = Task { try await Model.load(id: id) }
        loading[id] = task
        do {
            let model = try await task.value
            loading[id] = nil
            loaded[id] = model
            return model
        } catch {
            loading[id] = nil
            throw error
        }
    }
